<?php
declare(strict_types=1);
$isHttps=isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!==''&&$_SERVER['HTTPS']!=='off';ini_set('session.use_strict_mode','1');session_name('coaching_tool_session');session_set_cookie_params(['httponly'=>true,'secure'=>$isHttps,'samesite'=>'Strict','path'=>'/']);session_start();header('Cache-Control: no-store, private');require_once dirname(__DIR__).'/app/bootstrap.php';
function taskH(string|int|null $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$user=$_SESSION['user']??null;if(!is_array($user)||($user['role']??'')!=='coach'){http_response_code(403);exit('Nur Coaches haben Zugriff.');}
$db=coachingDatabase();$coach=(int)$user['id'];$token=$_SESSION['csrf_token']??'';if(!is_string($token)||strlen($token)!==64){$token=bin2hex(random_bytes(32));$_SESSION['csrf_token']=$token;}
$q=$db->prepare('SELECT id,vorname,nachname FROM klienten WHERE benutzer_id=:coach ORDER BY nachname,vorname');$q->execute(['coach'=>$coach]);$clients=$q->fetchAll(PDO::FETCH_ASSOC);
$selectedClient=filter_var($_GET['klient_id']??0,FILTER_VALIDATE_INT);$selectedClient=$selectedClient===false?0:(int)$selectedClient;
if($selectedClient>0&&!in_array($selectedClient,array_map(static fn($c)=>(int)$c['id'],$clients),true))$selectedClient=0;
$error='';$notice=isset($_GET['saved'])?'Die Aufgabe wurde gespeichert.':'';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($token,(string)($_POST['csrf_token']??''))){http_response_code(400);exit('Ungültige Anfrage.');}
try{$action=(string)($_POST['action']??'');if($action==='create'){$client=(int)($_POST['klient_id']??0);$title=trim((string)($_POST['titel']??''));$desc=trim((string)($_POST['beschreibung']??''));$due=trim((string)($_POST['faellig_am']??''));$check=$db->prepare('SELECT id FROM klienten WHERE id=:id AND benutzer_id=:coach');$check->execute(['id'=>$client,'coach'=>$coach]);if(!$check->fetchColumn()||$title===''||strlen($title)>190)throw new RuntimeException('Bitte Klient und Aufgabentitel angeben.');if($due!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$due))throw new RuntimeException('Bitte ein gültiges Fälligkeitsdatum auswählen.');$ins=$db->prepare("INSERT INTO coaching_aufgaben (klient_id,coach_benutzer_id,titel,beschreibung,faellig_am) VALUES (:client,:coach,:title,:description,:due)");$ins->execute(['client'=>$client,'coach'=>$coach,'title'=>$title,'description'=>$desc?:null,'due'=>$due?:null]);header('Location: tasks.php?saved=1');exit;}if($action==='status'){$task=(int)($_POST['task_id']??0);$status=(string)($_POST['status']??'');if(!in_array($status,['offen','in_bearbeitung','erledigt'],true))throw new RuntimeException('Ungültiger Aufgabenstatus.');$upd=$db->prepare('UPDATE coaching_aufgaben a INNER JOIN klienten k ON k.id=a.klient_id SET a.status=:status WHERE a.id=:id AND a.coach_benutzer_id=:coach AND k.benutzer_id=:owner');$upd->execute(['status'=>$status,'id'=>$task,'coach'=>$coach,'owner'=>$coach]);header('Location: tasks.php?saved=1');exit;}}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Aufgabe konnte nicht gespeichert werden.';error_log('Coaching Tool tasks error: '.$e->getMessage());}}
$q=$db->prepare('SELECT a.*,k.vorname,k.nachname FROM coaching_aufgaben a INNER JOIN klienten k ON k.id=a.klient_id WHERE a.coach_benutzer_id=:coach AND k.benutzer_id=:owner ORDER BY (a.status=\'erledigt\'),a.faellig_am IS NULL,a.faellig_am,a.erstellt_am DESC LIMIT 300');$q->execute(['coach'=>$coach,'owner'=>$coach]);$tasks=$q->fetchAll(PDO::FETCH_ASSOC);
?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Aufgaben</title><link rel="stylesheet" href="assets/layout.css"><style>.page{max-width:1180px;margin:auto;padding:34px clamp(24px,4vw,58px) 62px}.grid{display:grid;grid-template-columns:minmax(280px,360px) 1fr;gap:18px}.card{background:white;border:1px solid #e4ebe6;border-radius:14px;padding:20px;margin:18px 0}.form{display:grid;gap:10px}.form input,.form select,.form textarea{width:100%;padding:11px;border:1px solid #dce5df;border-radius:9px;font:inherit}.button{background:#245c50;color:white;border:0;border-radius:9px;padding:11px 15px;font:inherit}.task{border-top:1px solid #edf1ee;padding:13px 0}.meta{color:#708078;font-size:13px}.notice{background:#edf5ef;padding:12px}.error{background:#fff3f1;padding:12px}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style></head><body class="has-app-sidebar"><?php require_once dirname(__DIR__).'/app/navigation.php';renderCoachingSidebar($user,'tasks',$token);?><main class="page"><h1>Aufgaben und Übungen</h1><p>Lege konkrete nächste Schritte an und verfolge den Stand gemeinsam mit dem Coachee.</p><?php if($notice):?><p class="notice"><?=taskH($notice)?></p><?php endif;?><?php if($error):?><p class="error"><?=taskH($error)?></p><?php endif;?><div class="grid"><section class="card"><h2>Aufgabe anlegen</h2><form class="form" method="post"><input type="hidden" name="csrf_token" value="<?=taskH($token)?>"><input type="hidden" name="action" value="create"><label>Klient<select name="klient_id" required><option value="">Auswählen</option><?php foreach($clients as $c):?><option value="<?=(int)$c['id']?>" <?=(int)$selectedClient===(int)$c['id']?'selected':''?>><?=taskH($c['vorname'].' '.$c['nachname'])?></option><?php endforeach;?></select></label><label>Titel<input name="titel" maxlength="190" required></label><label>Beschreibung<textarea name="beschreibung" rows="4"></textarea></label><label>Fällig am<input type="date" name="faellig_am"></label><button class="button">Aufgabe speichern</button></form></section><section class="card"><h2>Aufgabenverlauf</h2><?php if(!$tasks):?><p>Noch keine Aufgaben eingetragen.</p><?php else:foreach($tasks as $t):?><article class="task"><strong><?=taskH($t['titel'])?></strong> · <a href="client-overview.php?id=<?=(int)$t['klient_id']?>"><?=taskH($t['vorname'].' '.$t['nachname'])?></a><p class="meta"><?=taskH($t['beschreibung']??'')?><?= $t['faellig_am']?' · Fällig '.taskH(date('d.m.Y',strtotime($t['faellig_am']))):''?> · <?=$t['klient_sichtbar']?'Für Klient sichtbar':'Nur Coach'?></p><form method="post"><input type="hidden" name="csrf_token" value="<?=taskH($token)?>"><input type="hidden" name="action" value="status"><input type="hidden" name="task_id" value="<?=(int)$t['id']?>"><select name="status"><option value="offen" <?=$t['status']==='offen'?'selected':''?>>Offen</option><option value="in_bearbeitung" <?=$t['status']==='in_bearbeitung'?'selected':''?>>In Bearbeitung</option><option value="erledigt" <?=$t['status']==='erledigt'?'selected':''?>>Erledigt</option></select> <button class="button">Stand speichern</button></form></article><?php endforeach;endif;?></section></div></main></body></html>